```yaml
name: Deploy Jupyter Notebook to GitHub Pages

on:
  push:
    branches: [ main ]
  workflow_dispatch:

permissions:
  contents: read
  pages: write
  id-token: write

concurrency:
  group: "pages"
  cancel-in-progress: false

jobs:
  build:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout
        uses: actions/checkout@v4

      - name: Set up Python
        uses: actions/setup-python@v4
        with:
          python-version: '3.9'

      - name: Install dependencies
        run: |
          pip install jupyter nbconvert

      - name: Convert notebook to HTML
        run: |
          jupyter nbconvert --to html --no-input dr-manhattan.ipynb

      - name: Create landing page
        run: |
          cat > index.html << 'EOF'
          <!DOCTYPE html>
          <html lang="en">
          <head>
              <meta charset="UTF-8">
              <meta name="viewport" content="width=device-width, initial-scale=1.0">
              <title>Dr. Manhattan - Jupyter Extension</title>
              <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0/css/all.min.css">
              <style>
                  :root {
                      --primary: #00f3ff;
                      --secondary: #0066ff;
                      --dark: #0a0a1a;
                      --darker: #050510;
                      --light: #e0e0ff;
                  }

                  * {
                      margin: 0;
                      padding: 0;
                      box-sizing: border-box;
                      font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
                  }

                  body {
                      background: var(--darker);
                      color: var(--light);
                      min-height: 100vh;
                      overflow-x: hidden;
                      position: relative;
                  }

                  body::before {
                      content: '';
                      position: absolute;
                      top: 0;
                      left: 0;
                      width: 100%;
                      height: 100%;
                      background: 
                          radial-gradient(circle at 10% 20%, rgba(0, 243, 255, 0.1) 0%, transparent 20%),
                          radial-gradient(circle at 90% 80%, rgba(0, 102, 255, 0.1) 0%, transparent 20%);
                      z-index: -1;
                  }

                  .container {
                      max-width: 1200px;
                      margin: 0 auto;
                      padding: 2rem;
                  }

                  header {
                      text-align: center;
                      padding: 3rem 0;
                      animation: fadeIn 1s ease-out;
                  }

                  .logo {
                      font-size: 4rem;
                      margin-bottom: 1rem;
                      color: var(--primary);
                      text-shadow: 0 0 15px rgba(0, 243, 255, 0.7);
                      animation: pulse 2s infinite;
                  }

                  h1 {
                      font-size: 3rem;
                      margin-bottom: 1rem;
                      background: linear-gradient(to right, var(--primary), var(--secondary));
                      -webkit-background-clip: text;
                      -webkit-text-fill-color: transparent;
                      text-shadow: 0 0 10px rgba(0, 243, 255, 0.3);
                  }

                  .subtitle {
                      font-size: 1.2rem;
                      opacity: 0.8;
                      max-width: 600px;
                      margin: 0 auto 2rem;
                  }

                  .install-section {
                      background: rgba(10, 10, 26, 0.7);
                      border-radius: 15px;
                      padding: 2rem;
                      margin: 2rem 0;
                      border: 1px solid rgba(0, 243, 255, 0.2);
                      backdrop-filter: blur(10px);
                      box-shadow: 0 0 20px rgba(0, 243, 255, 0.1);
                      animation: slideUp 0.8s ease-out;
                  }

                  .install-command {
                      display: flex;
                      align-items: center;
                      gap: 1rem;
                      background: rgba(0, 0, 0, 0.3);
                      padding: 1rem;
                      border-radius: 8px;
                      margin-top: 1rem;
                      border: 1px solid rgba(0, 243, 255, 0.3);
                  }

                  .command {
                      flex: 1;
                      font-family: monospace;
                      background: rgba(0, 0, 0, 0.5);
                      padding: 0.5rem;
                      border-radius: 4px;
                      color: var(--primary);
                      overflow-x: auto;
                  }

                  .copy-btn {
                      background: var(--secondary);
                      color: white;
                      border: none;
                      padding: 0.5rem 1rem;
                      border-radius: 4px;
                      cursor: pointer;
                      transition: all 0.3s ease;
                      font-weight: bold;
                  }

                  .copy-btn:hover {
                      background: var(--primary);
                      box-shadow: 0 0 10px rgba(0, 243, 255, 0.5);
                  }

                  .features {
                      display: grid;
                      grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
                      gap: 2rem;
                      margin: 3rem 0;
                  }

                  .feature-card {
                      background: rgba(10, 10, 26, 0.7);
                      border-radius: 15px;
                      padding: 2rem;
                      border: 1px solid rgba(0, 243, 255, 0.2);
                      transition: transform 0.3s ease, box-shadow 0.3s ease;
                      backdrop-filter: blur(10px);
                      animation: fadeIn 0.8s ease-out;
                      animation-fill-mode: both;
                  }

                  .feature-card:hover {
                      transform: translateY(-10px);
                      box-shadow: 0 10px 25px rgba(0, 243, 255, 0.2);
                      border-color: var(--primary);
                  }

                  .feature-icon {
                      font-size: 2.5rem;
                      color: var(--primary);
                      margin-bottom: 1rem;
                  }

                  .feature-title {
                      font-size: 1.5rem;
                      margin-bottom: 1rem;
                      color: var(--primary);
                  }

                  .feature-desc {
                      opacity: 0.8;
                      line-height: 1.6;
                  }

                  .logos {
                      display: flex;
                      justify-content: center;
                      flex-wrap: wrap;
                      gap: 2rem;
                      margin: 3rem 0;
                      padding: 2rem;
                      background: rgba(10, 10, 26, 0.5);
                      border-radius: 15px;
                      border: 1px solid rgba(0, 243, 255, 0.2);
                  }

                  .logo-item {
                      filter: grayscale(100%);
                      opacity: 0.7;
                      transition: all 0.3s ease;
                      height: 60px;
                      display: flex;
                      align-items: center;
                      justify-content: center;
                  }

                  .logo-item:hover {
                      filter: grayscale(0);
                      opacity: 1;
                      transform: scale(1.1);
                  }

                  footer {
                      text-align: center;
                      padding: 3rem 0;
                      opacity: 0.7;
                      font-size: 0.9rem;
                  }

                  @keyframes fadeIn {
                      from { opacity: 0; }
                      to { opacity: 1; }
                  }

                  @keyframes slideUp {
                      from { 
                          opacity: 0;
                          transform: translateY(30px);
                      }
                      to { 
                          opacity: 1;
                          transform: translateY(0);
                      }
                  }

                  @keyframes pulse {
                      0% { text-shadow: 0 0 10px rgba(0, 243, 255, 0.5); }
                      50% { text-shadow: 0 0 20px rgba(0, 243, 255, 0.8), 0 0 30px rgba(0, 102, 255, 0.6); }
                      100% { text-shadow: 0 0 10px rgba(0, 243, 255, 0.5); }
                  }

                  @media (max-width: 768px) {
                      .container {
                          padding: 1rem;
                      }

                      h1 {
                          font-size: 2rem;
                      }

                      .install-command {
                          flex-direction: column;
                      }
                  }
              </style>
          </head>
          <body>
              <div class="container">
                  <header>
                      <div class="logo">
                          <i class="fas fa-brain"></i>
                      </div>
                      <h1>Dr. Manhattan</h1>
                      <p class="subtitle">Advanced Jupyter Notebook Extension for Enhanced Data Science Workflow</p>
                  </header>

                  <section class="install-section">
                      <h2><i class="fas fa-download"></i> Installation</h2>
                      <p>Install Dr. Manhattan directly from PyPI:</p>
                      <div class="install-command">
                          <div class="command">pip install dr-manhattan</div>
                          <button class="copy-btn" onclick="copyCommand()">Copy</button>
                      </div>
                  </section>

                  <section class="features">
                      <div class="feature-card">
                          <div class="feature-icon">
                              <i class="fas fa-code"></i>
                          </div>
                          <h3 class="feature-title">Code Enhancement</h3>
                          <p class="feature-desc">Advanced syntax highlighting and code completion for Jupyter notebooks with support for multiple programming languages.</p>
                      </div>

                      <div class="feature-card">
                          <div class="feature-icon">
                              <i class="fas fa-chart-line"></i>
                          </div>
                          <h3 class="feature-title">Data Visualization</h3>
                          <p class="feature-desc">Interactive charts and graphs with real-time data visualization capabilities for better insights and analysis.</p>
                      </div>

                      <div class="feature-card">
                          <div class="feature-icon">
                              <i class="fas fa-bolt"></i>
                          </div>
                          <h3 class="feature-title">Performance Boost</h3>
                          <p class="feature-desc">Optimized execution engine that significantly speeds up notebook processing and rendering times.</p>
                      </div>
                  </section>

                  <section class="logos">
                      <div class="logo-item">
                          <i class="fab fa-python fa-2x"></i>
                      </div>
                      <div class="logo-item">
                          <i class="fab fa-jupyter fa-2x"></i>
                      </div>
                      <div class="logo-item">
                          <i class="fab fa-github fa-2x"></i>
                      </div>
                      <div class="logo-item">
                          <i class="fab fa-google fa-2x"></i>
                      </div>
                  </section>

                  <footer>
                      <p>Dr. Manhattan - Advanced Jupyter Extension | Made with <i class="fas fa-heart" style="color: #ff0055;"></i></p>
                      <p>© 2023 Dr. Manhattan. All rights reserved.</p>
                  </footer>
              </div>

              <script>
                  function copyCommand() {
                      const command = document.querySelector('.command').textContent;
                      navigator.clipboard.writeText(command).then(() => {
                          const btn = document.querySelector('.copy-btn');
                          btn.textContent = 'Copied!';
                          setTimeout(() => {
                              btn.textContent = 'Copy';
                          }, 2000);
                      });
                  }
              </script>
          </body>
          </html>
          EOF

      - name: Upload artifact
        uses: actions/upload-pages-artifact@v2
        with:
          path: .

  deploy:
    environment:
      name: github-pages
      url: ${{ steps.deployment.outputs.page_url }}
    runs-on: ubuntu-latest
    needs: build
    steps:
      - name: Deploy to GitHub Pages
        id: deployment
        uses: actions/deploy-pages@v2
